type PolicyEngine interface{EvaluateImage(context.Context,ID,ImageReference)(ImagePolicyReceipt,error);AuthorizeTier(context.Context,Grant,RuntimeTier,string)error;ValidateWorkload(context.Context,ID,RuntimeTier,WorkloadSpec)error;ValidateExposure(context.Context,ID,Exposure)error}
type RouteCoordinator interface{Prepare(context.Context,Exposure)(uint64,error);Commit(context.Context,Exposure,uint64)(uint64,error);Rollback(context.Context,Exposure,uint64)error;Withdraw(context.Context,Exposure)(uint64,error)}
type BackupCoordinator interface{SnapshotVolumes(context.Context,ID,[]ID)(string,error);RestoreVolumes(context.Context,string,[]ID)error}
type Service struct{repository Repository;broker Broker;policy PolicyEngine;routes RouteCoordinator;backups BackupCoordinator;clock func()time.Time}
func NewService(repository Repository,broker Broker,policy PolicyEngine,routes RouteCoordinator,backups BackupCoordinator)(*Service,error){if nilValue(repository)||nilValue(broker)||nilValue(policy)||nilValue(routes)||nilValue(backups){return nil,ErrInvalid};return &Service{repository:repository,broker:broker,policy:policy,routes:routes,backups:backups,clock:time.Now},nil}

type CommandMeta struct{CommandID string;Grant Grant;ExpectedGeneration uint64;Fence FenceToken}
func(m CommandMeta)Validate(operation string,resource ID,now time.Time)error{if m.CommandID==""||len(m.CommandID)>160||m.Fence==0||!m.Grant.TenantID.Valid()||m.Grant.ResourceID!=resource||m.Grant.Operation!=operation||m.Grant.AuthzEpoch==0||!now.Before(m.Grant.ExpiresAt)||len(m.Grant.Digest)!=64{return ErrForbidden};return nil}
type Result struct{EffectID EffectID;Status string;ResourceID ID;Generation uint64;Receipt any}

type PullImageCommand struct{Meta CommandMeta;ImageID ID;RegistryCredentialID ID;Registry,Repository,Tag,Platform string}
func(s *Service)PullImage(_ context.Context,command PullImageCommand)(Image,Result,error){return Image{},Result{Status:"rejected",ResourceID:command.ImageID},fmt.Errorf("%w: remote image pulls disabled; use an already-present digest-pinned image",ErrPolicy)}

