type ApplyWorkloadCommand struct{Meta CommandMeta;WorkloadID,ProjectID,SiteID ID;Name string;Tier RuntimeTier;Spec WorkloadSpec}
func(s *Service)ApplyWorkload(ctx context.Context,command ApplyWorkloadCommand)(Workload,Result,error){now:=s.clock().UTC();if err:=command.Meta.Validate("workload.apply",command.WorkloadID,now);err!=nil{return Workload{},Result{},err};if err:=s.policy.AuthorizeTier(ctx,command.Meta.Grant,command.Tier,"apply");err!=nil{return Workload{},Result{},err};if err:=command.Spec.Validate(command.Tier);err!=nil{return Workload{},Result{},err};if err:=s.policy.ValidateWorkload(ctx,command.Meta.Grant.TenantID,command.Tier,command.Spec);err!=nil{return Workload{},Result{},err};effect,digest,operation,existing,err:=s.operation(ctx,command.Meta,command.WorkloadID,command);if err!=nil||existing{return Workload{},resultFromOperation(operation),err};specDigest:=digestValue(command.Spec);workload:=Workload{ID:command.WorkloadID,TenantID:command.Meta.Grant.TenantID,ProjectID:command.ProjectID,SiteID:command.SiteID,Name:strings.TrimSpace(command.Name),Tier:command.Tier,Spec:command.Spec,DesiredLifecycle:LifecycleRunning,ObservedLifecycle:LifecyclePending,ObservedHealth:HealthUnknown,SpecDigest:specDigest,Generation:command.Meta.ExpectedGeneration+1,CreatedAt:now,UpdatedAt:now};if previous,loadErr:=s.repository.Workload(ctx,workload.TenantID,workload.ID);loadErr==nil{workload.CreatedAt=previous.CreatedAt;workload.ObservedLifecycle=previous.ObservedLifecycle;workload.ObservedHealth=previous.ObservedHealth;workload.ObservedGeneration=previous.ObservedGeneration;workload.RuntimeObjectID=previous.RuntimeObjectID;workload.RestartCount=previous.RestartCount};if err=workload.Validate();err!=nil{return Workload{},Result{},err};operation.CommandDigest=digest;admitted,err:=s.repository.Admit(ctx,operation,workload,command.Meta.ExpectedGeneration);if err!=nil{return Workload{},Result{},err};if !admitted{return workload,resultFromOperation(operation),nil};request:=WorkloadMutationRequest{EffectID:effect,Grant:command.Meta.Grant,WorkloadID:workload.ID,ExpectedGeneration:command.Meta.ExpectedGeneration,Tier:workload.Tier,Spec:workload.Spec,SpecDigest:workload.SpecDigest,Fence:command.Meta.Fence};receipt,err:=s.broker.ApplyWorkload(ctx,request);if err!=nil{if errors.Is(err,ErrNotFound)||errors.Is(err,ErrPolicy)||errors.Is(err,ErrInvalid)||errors.Is(err,ErrForbidden){return workload,s.reject(ctx,operation,workload,err)};return workload,s.ambiguous(ctx,operation,workload,err)};if !validConfirmedWorkloadReceipt(receipt,effect,workload.ID,workload.Generation,workload.SpecDigest){return workload,s.ambiguous(ctx,operation,workload,ErrContainerBrokerProtocol)};workload.RuntimeObjectID=receipt.RuntimeObjectID;workload.ObservedDigest=receipt.ObservedDigest;workload.ObservedLifecycle=receipt.Lifecycle;workload.ObservedHealth=receipt.Health;workload.ObservedGeneration=workload.Generation;workload.UpdatedAt=s.clock().UTC();if err=s.repository.Complete(ctx,effect,"applied",workload,receipt);err!=nil{return workload,Result{EffectID:effect,Status:"ambiguous",ResourceID:workload.ID,Generation:workload.Generation,Receipt:receipt},err};return workload,Result{EffectID:effect,Status:"applied",ResourceID:workload.ID,Generation:workload.Generation,Receipt:receipt},nil}

type LifecycleCommand struct{Meta CommandMeta;WorkloadID ID;Lifecycle Lifecycle;CommitAuthorizationDigest string}
func(s *Service)SetLifecycle(ctx context.Context,command LifecycleCommand)(Workload,Result,error){now:=s.clock().UTC();if err:=command.Meta.Validate("workload.lifecycle",command.WorkloadID,now);err!=nil{return Workload{},Result{},err};if command.Lifecycle!=LifecycleRunning&&command.Lifecycle!=LifecycleStopped&&command.Lifecycle!=LifecycleDeleting{return Workload{},Result{},ErrInvalid};workload,err:=s.repository.Workload(ctx,command.Meta.Grant.TenantID,command.WorkloadID);if err!=nil{return Workload{},Result{},err};if workload.Generation!=command.Meta.ExpectedGeneration{return Workload{},Result{},ErrStale};effect,digest,operation,existing,err:=s.operation(ctx,command.Meta,command.WorkloadID,command);if err!=nil||existing{return workload,resultFromOperation(operation),err};workload.DesiredLifecycle=command.Lifecycle;workload.Generation++;workload.UpdatedAt=now;operation.CommandDigest=digest;admitted,err:=s.repository.Admit(ctx,operation,workload,command.Meta.ExpectedGeneration);if err!=nil{return workload,Result{},err};if !admitted{return workload,resultFromOperation(operation),nil};receipt,err:=s.broker.SetLifecycle(ctx,WorkloadLifecycleRequest{EffectID:effect,Grant:command.Meta.Grant,WorkloadID:workload.ID,ExpectedGeneration:command.Meta.ExpectedGeneration,Lifecycle:command.Lifecycle,Fence:command.Meta.Fence,CommitAuthorizationDigest:command.CommitAuthorizationDigest});if err!=nil{return workload,s.ambiguous(ctx,operation,workload,err)};if !validConfirmedWorkloadReceipt(receipt,effect,workload.ID,workload.Generation,workload.SpecDigest){return workload,s.ambiguous(ctx,operation,workload,ErrContainerBrokerProtocol)};workload.ObservedLifecycle=receipt.Lifecycle;workload.ObservedHealth=receipt.Health;workload.ObservedGeneration=workload.Generation;workload.ObservedDigest=receipt.ObservedDigest;if command.Lifecycle==LifecycleDeleting{workload.DesiredLifecycle=LifecycleDeleted;workload.ObservedLifecycle=LifecycleDeleted;workload.ObservedHealth=HealthUnavailable;deleted:=s.clock().UTC();workload.DeletedAt=&deleted};if err=s.repository.Complete(ctx,effect,"applied",workload,receipt);err!=nil{return workload,Result{EffectID:effect,Status:"ambiguous",ResourceID:workload.ID,Generation:workload.Generation,Receipt:receipt},err};return workload,Result{EffectID:effect,Status:"applied",ResourceID:workload.ID,Generation:workload.Generation,Receipt:receipt},nil}

type RestartWorkloadCommand struct{Meta CommandMeta;WorkloadID ID;CommitAuthorizationDigest string}
func(s *Service)RestartWorkload(ctx context.Context,command RestartWorkloadCommand)(Workload,Result,error){now:=s.clock().UTC();if err:=command.Meta.Validate("workload.restart",command.WorkloadID,now);err!=nil{return Workload{},Result{},err};workload,err:=s.repository.Workload(ctx,command.Meta.Grant.TenantID,command.WorkloadID);if err!=nil{return Workload{},Result{},err};if workload.Generation!=command.Meta.ExpectedGeneration{return Workload{},Result{},ErrStale};effect,digest,operation,existing,err:=s.operation(ctx,command.Meta,command.WorkloadID,command);if err!=nil||existing{return workload,resultFromOperation(operation),err};workload.DesiredLifecycle=LifecycleRunning;workload.Generation++;workload.UpdatedAt=now;operation.CommandDigest=digest;admitted,err:=s.repository.Admit(ctx,operation,workload,command.Meta.ExpectedGeneration);if err!=nil{return workload,Result{},err};if !admitted{return workload,resultFromOperation(operation),nil};receipt,err:=s.broker.RestartWorkload(ctx,WorkloadRestartRequest{EffectID:effect,Grant:command.Meta.Grant,WorkloadID:workload.ID,ExpectedGeneration:command.Meta.ExpectedGeneration,Fence:command.Meta.Fence,CommitAuthorizationDigest:command.CommitAuthorizationDigest});if err!=nil{return workload,s.ambiguous(ctx,operation,workload,err)};if !validConfirmedWorkloadReceipt(receipt,effect,workload.ID,workload.Generation,workload.SpecDigest)||receipt.Lifecycle!=LifecycleRunning{return workload,s.ambiguous(ctx,operation,workload,ErrContainerBrokerProtocol)};workload.ObservedLifecycle=receipt.Lifecycle;workload.ObservedHealth=receipt.Health;workload.ObservedGeneration=workload.Generation;workload.ObservedDigest=receipt.ObservedDigest;workload.RestartCount++;if err=s.repository.Complete(ctx,effect,"applied",workload,receipt);err!=nil{return workload,Result{EffectID:effect,Status:"ambiguous",ResourceID:workload.ID,Generation:workload.Generation,Receipt:receipt},err};return workload,Result{EffectID:effect,Status:"applied",ResourceID:workload.ID,Generation:workload.Generation,Receipt:receipt},nil}

type ApplyExposureCommand struct{Meta CommandMeta;Exposure Exposure}
func(s *Service)ApplyExposure(ctx context.Context,command ApplyExposureCommand)(Exposure,Result,error){now:=s.clock().UTC();command.Exposure.TenantID=command.Meta.Grant.TenantID;if err:=command.Meta.Validate("exposure.apply",command.Exposure.ID,now);err!=nil{return Exposure{},Result{},err};command.Exposure.Generation=command.Meta.ExpectedGeneration+1;command.Exposure.State="preparing";if err:=s.policy.ValidateExposure(ctx,command.Meta.Grant.TenantID,command.Exposure);err!=nil{return Exposure{},Result{},err};workload,err:=s.repository.Workload(ctx,command.Exposure.TenantID,command.Exposure.WorkloadID);if err!=nil{return Exposure{},Result{},err};if workload.ObservedLifecycle!=LifecycleRunning{return Exposure{},Result{},ErrConflict};effect,digest,operation,existing,err:=s.operation(ctx,command.Meta,command.Exposure.ID,command);if err!=nil||existing{return command.Exposure,resultFromOperation(operation),err};operation.CommandDigest=digest;admitted,err:=s.repository.Admit(ctx,operation,command.Exposure,command.Meta.ExpectedGeneration);if err!=nil{return command.Exposure,Result{},err};if !admitted{return command.Exposure,resultFromOperation(operation),nil};routeGeneration:=uint64(0);if command.Exposure.Public{routeGeneration,err=s.routes.Prepare(ctx,command.Exposure);if err!=nil{return command.Exposure,s.reject(ctx,operation,command.Exposure,err)}};request:=ExposureMutationRequest{EffectID:effect,Grant:command.Meta.Grant,Exposure:command.Exposure,ExpectedGeneration:command.Meta.ExpectedGeneration,Fence:command.Meta.Fence};receipt,err:=s.broker.ApplyExposure(ctx,request);if err!=nil{if routeGeneration!=0{_=s.routes.Rollback(ctx,command.Exposure,routeGeneration)};return command.Exposure,s.ambiguous(ctx,operation,command.Exposure,err)};if receipt.Outcome!="confirmed"||receipt.EffectID!=effect||receipt.ExposureID!=command.Exposure.ID||receipt.Generation!=command.Exposure.Generation||receipt.Fence!=command.Meta.Fence||receipt.ConfigurationDigest!=exposureConfigurationDigest(command.Exposure)||receipt.BoundAddress!="127.0.0.1"||receipt.BoundPort!=LoopbackExposurePort(command.Exposure.WorkloadID,command.Exposure.PortName)||receipt.Public!=command.Exposure.Public||receipt.ObservedAt.IsZero(){if routeGeneration!=0{_=s.routes.Rollback(ctx,command.Exposure,routeGeneration)};return command.Exposure,s.ambiguous(ctx,operation,command.Exposure,ErrContainerBrokerProtocol)};if command.Exposure.Public{committed,commitErr:=s.routes.Commit(ctx,command.Exposure,routeGeneration);if commitErr!=nil{_=s.routes.Rollback(ctx,command.Exposure,routeGeneration);compensation:=request;compensation.EffectID=EffectID(string(effect)+"-compensate");compensation.Grant.Operation="exposure.delete";_,compensationErr:=s.broker.DeleteExposure(ctx,compensation);return command.Exposure,s.ambiguous(ctx,operation,command.Exposure,errors.Join(commitErr,compensationErr))};receipt.RouteGeneration=committed;receipt.FirewallGeneration=committed};command.Exposure.State="active";if err=s.repository.Complete(ctx,effect,"applied",command.Exposure,receipt);err!=nil{return command.Exposure,Result{EffectID:effect,Status:"ambiguous",ResourceID:command.Exposure.ID,Generation:command.Exposure.Generation,Receipt:receipt},err};return command.Exposure,Result{EffectID:effect,Status:"applied",ResourceID:command.Exposure.ID,Generation:command.Exposure.Generation,Receipt:receipt},nil}
type DeleteExposureCommand struct{Meta CommandMeta;ExposureID ID}
func(s *Service)DeleteExposure(ctx context.Context,command DeleteExposureCommand)(Exposure,Result,error){now:=s.clock().UTC();if err:=command.Meta.Validate("exposure.delete",command.ExposureID,now);err!=nil{return Exposure{},Result{},err};exposure,err:=s.repository.Exposure(ctx,command.Meta.Grant.TenantID,command.ExposureID);if err!=nil{return Exposure{},Result{},err};if exposure.Generation!=command.Meta.ExpectedGeneration{return exposure,Result{},ErrStale};effect,digest,operation,existing,err:=s.operation(ctx,command.Meta,command.ExposureID,command);if err!=nil||existing{return exposure,resultFromOperation(operation),err};exposure.Generation++;exposure.State="deleting";operation.CommandDigest=digest;admitted,err:=s.repository.Admit(ctx,operation,exposure,command.Meta.ExpectedGeneration);if err!=nil{return exposure,Result{},err};if !admitted{return exposure,resultFromOperation(operation),nil};withdrawn:=uint64(0);if exposure.Public{withdrawn,err=s.routes.Withdraw(ctx,exposure);if err!=nil{return exposure,s.ambiguous(ctx,operation,exposure,err)}};receipt,err:=s.broker.DeleteExposure(ctx,ExposureMutationRequest{EffectID:effect,Grant:command.Meta.Grant,Exposure:exposure,ExpectedGeneration:command.Meta.ExpectedGeneration,Fence:command.Meta.Fence});if err!=nil{return exposure,s.ambiguous(ctx,operation,exposure,err)};if receipt.Outcome!="confirmed"||receipt.EffectID!=effect||receipt.ExposureID!=exposure.ID||receipt.Generation!=exposure.Generation||receipt.Fence!=command.Meta.Fence||receipt.ConfigurationDigest==""||receipt.BoundAddress!="127.0.0.1"||receipt.BoundPort!=LoopbackExposurePort(exposure.WorkloadID,exposure.PortName){return exposure,s.ambiguous(ctx,operation,exposure,ErrContainerBrokerProtocol)};receipt.RouteGeneration=withdrawn;receipt.FirewallGeneration=withdrawn;exposure.State="deleted";if err=s.repository.Complete(ctx,effect,"applied",exposure,receipt);err!=nil{return exposure,Result{EffectID:effect,Status:"ambiguous",ResourceID:exposure.ID,Generation:exposure.Generation,Receipt:receipt},err};return exposure,Result{EffectID:effect,Status:"applied",ResourceID:exposure.ID,Generation:exposure.Generation,Receipt:receipt},nil}

func(s *Service)IssueExecGrant(ctx context.Context,grant Grant,id,workloadID,commandID ID,user RuntimeUser,args []string,ttl time.Duration,assuranceDigest string)(ExecGrant,error){if err:=grantValid(grant,"workload.exec",workloadID,s.clock().UTC());err!=nil{return ExecGrant{},err};workload,err:=s.repository.Workload(ctx,grant.TenantID,workloadID);if err!=nil{return ExecGrant{},err};if err=s.policy.AuthorizeTier(ctx,grant,workload.Tier,"exec");err!=nil{return ExecGrant{},err};if err=user.Validate(workload.Tier);err!=nil{return ExecGrant{},err};if ttl<=0||ttl>15*time.Minute{ttl=5*time.Minute};value:=ExecGrant{ID:id,TenantID:grant.TenantID,WorkloadID:workloadID,Tier:workload.Tier,RuntimeUser:user,CommandID:commandID,Arguments:append([]string(nil),args...),AssuranceDigest:assuranceDigest,ExpiresAt:s.clock().UTC().Add(ttl)};if err=s.repository.IssueExecGrant(ctx,value);err!=nil{return ExecGrant{},err};return value,nil}
func(s *Service)Exec(ctx context.Context,meta CommandMeta,grantID ID)(ExecReceipt,error){now:=s.clock().UTC();grant,err:=s.repository.ConsumeExecGrant(ctx,grantID,now);if err!=nil{return ExecReceipt{},err};if err=meta.Validate("workload.exec",grant.WorkloadID,now);err!=nil{return ExecReceipt{},err};effect,_,_,_,err:=s.operation(ctx,meta,grant.WorkloadID,grant);if err!=nil{return ExecReceipt{},err};return s.broker.Exec(ctx,ExecRequest{EffectID:effect,Grant:meta.Grant,ExecGrant:grant,Fence:meta.Fence})}
func(s *Service)ExchangeExec(ctx context.Context,grantID ID,token string)(ExecReceipt,error){if s==nil||ctx==nil||!grantID.Valid()||len(token)<32||len(token)>512||strings.ContainsAny(token,"\x00\r\n\t "){return ExecReceipt{},ErrForbidden};stored,err:=s.repository.ExecGrant(ctx,grantID);if err!=nil{return ExecReceipt{},err};now:=s.clock().UTC();if stored.ConsumedAt!=nil||!now.Before(stored.ExpiresAt)||len(stored.AssuranceDigest)!=64{return ExecReceipt{},ErrForbidden};sum:=sha256.Sum256([]byte(token));actual:=hex.EncodeToString(sum[:]);if subtle.ConstantTimeCompare([]byte(actual),[]byte(stored.AssuranceDigest))!=1{return ExecReceipt{},ErrForbidden};workload,err:=s.repository.Workload(ctx,stored.TenantID,stored.WorkloadID);if err!=nil{return ExecReceipt{},err};grant:=Grant{TenantID:stored.TenantID,ResourceID:stored.WorkloadID,Operation:"workload.exec",AuthzEpoch:1,ExpiresAt:stored.ExpiresAt,Digest:stored.AssuranceDigest};meta:=CommandMeta{CommandID:"exec-exchange-"+stored.ID.String(),Grant:grant,ExpectedGeneration:workload.Generation,Fence:FenceToken(workload.Generation+1)};return s.Exec(ctx,meta,stored.ID)}

func(s *Service)Reconcile(ctx context.Context,tenant,workloadID ID,grant Grant)(Workload,error){workload,err:=s.repository.Workload(ctx,tenant,workloadID);if err!=nil{return Workload{},err};if tenant!=grant.TenantID{return Workload{},ErrForbidden};if err=grantValid(grant,"workload.reconcile",workloadID,s.clock().UTC());err!=nil{return Workload{},err};receipt,err:=s.broker.ObserveWorkload(ctx,WorkloadObservationRequest{Grant:grant,WorkloadID:workload.ID,ExpectedGeneration:workload.Generation});if err!=nil{return workload,err};if receipt.Outcome!="confirmed"||receipt.ResourceID!=workload.ID||receipt.Generation!=workload.Generation||receipt.SpecDigest!=workload.SpecDigest||receipt.ObservedDigest!=workload.SpecDigest||receipt.RuntimeObjectID==""||!validLifecycle(receipt.Lifecycle)||!validWorkloadHealth(receipt.Health){return workload,ErrContainerBrokerProtocol};workload.ObservedLifecycle=receipt.Lifecycle;workload.ObservedHealth=receipt.Health;workload.ObservedDigest=receipt.ObservedDigest;workload.RuntimeObjectID=receipt.RuntimeObjectID;workload.ObservedGeneration=workload.Generation;workload.UpdatedAt=s.clock().UTC();return workload,nil}

func(s *Service)operation(ctx context.Context,meta CommandMeta,resource ID,payload any)(EffectID,string,Operation,bool,error){digest:=digestValue(struct{Version int;CommandID string;Tenant ID;Resource ID;Payload any}{1,meta.CommandID,meta.Grant.TenantID,resource,payload});effect:=EffectID("ctr-"+digest);existing,found,err:=s.repository.Operation(ctx,effect);if err!=nil{return effect,digest,Operation{},false,err};if found{if existing.CommandDigest!=digest||existing.TenantID!=meta.Grant.TenantID||existing.ResourceID!=resource{return effect,digest,existing,true,ErrConflict};return effect,digest,existing,true,nil};raw,_:=json.Marshal(payload);return effect,digest,Operation{EffectID:effect,TenantID:meta.Grant.TenantID,ResourceID:resource,CommandDigest:digest,Status:"accepted",Request:raw,CreatedAt:s.clock().UTC()},false,nil}
func(s *Service)ambiguous(ctx context.Context,operation Operation,resource any,cause error)(Result,error){_ = s.repository.Complete(ctx,operation.EffectID,"ambiguous",resource,map[string]string{"code":"BROKER_EFFECT_AMBIGUOUS"});return Result{EffectID:operation.EffectID,Status:"ambiguous",ResourceID:operation.ResourceID,Generation:resourceGeneration(resource)},errors.Join(ErrAmbiguous,cause)}
func(s *Service)reject(ctx context.Context,operation Operation,resource any,cause error)(Result,error){_ = s.repository.Complete(ctx,operation.EffectID,"rejected",resource,map[string]string{"code":"EFFECT_REJECTED"});return Result{EffectID:operation.EffectID,Status:"rejected",ResourceID:operation.ResourceID,Generation:resourceGeneration(resource)},cause}
func resultFromOperation(operation Operation)Result{return Result{EffectID:operation.EffectID,Status:operation.Status,ResourceID:operation.ResourceID,Receipt:operation.Receipt}}
func imageFromOperation(operation Operation)Image{var value Image;_ = json.Unmarshal(operation.Receipt,&value);return value}
func digestValue(value any)string{raw,_:=json.Marshal(value);sum:=sha256.Sum256(raw);return hex.EncodeToString(sum[:])}
func grantValid(grant Grant,operation string,resource ID,now time.Time)error{if !grant.TenantID.Valid()||grant.ResourceID!=resource||grant.Operation!=operation||grant.AuthzEpoch==0||!now.Before(grant.ExpiresAt)||len(grant.Digest)!=64{return ErrForbidden};return nil}
func validConfirmedWorkloadReceipt(receipt RuntimeReceipt,effect EffectID,resource ID,generation uint64,specDigest string)bool{return receipt.Outcome=="confirmed"&&receipt.EffectID==effect&&receipt.ResourceID==resource&&receipt.Generation==generation&&receipt.RuntimeObjectID!=""&&receipt.SpecDigest==specDigest&&receipt.ObservedDigest==specDigest&&validLifecycle(receipt.Lifecycle)&&validWorkloadHealth(receipt.Health)&&!receipt.ObservedAt.IsZero()}
func nilValue(value any)bool{if value==nil{return true};ref:=reflect.ValueOf(value);switch ref.Kind(){case reflect.Pointer,reflect.Interface,reflect.Map,reflect.Slice,reflect.Func,reflect.Chan:return ref.IsNil()};return false}
